svg.script:
const NS = 'http://www.w3.org/2000/svg';
const COL = {
  main: ['#D3D1C7', '#2C2C2A'],
  A: ['#5DCAA5', '#04342C'],
  B: ['#AFA9EC', '#26215C'],
  C: ['#F0997B', '#4A1B0C']
};
const S = [
  {q:[],r:'main',w:[],d:[],t:'main is running',c:'It is the only thing on the thread. Nothing else exists yet.',k:'async def main():'},
  {q:['A','B','C'],r:'main',w:[],d:[],t:'create_task only queues',c:'Three tasks are scheduled. None has started, because main still holds the thread.',k:'tasks = [asyncio.create_task(work(n)) for n in "ABC"]'},
  {q:['A','B','C'],r:null,w:['main'],d:[],t:'main awaits and suspends',c:'main waits for tasks that are not done, so it steps aside. The thread is free.',k:'results = await asyncio.gather(*tasks)'},
  {q:['B','C'],r:'A',w:['main'],d:[],t:'The loop takes the front of the queue',c:'A gets the thread and runs its first lines.',k:'# in A: build the request and send it'},
  {q:['B','C'],r:null,w:['main','A'],d:[],t:'A awaits the network and suspends',c:'The request is out. A has nothing to do until the response arrives, so it leaves the thread.',k:'resp = await client.get(url)   # in A'},
  {q:['C'],r:'B',w:['main','A'],d:[],t:'Next in line: B',c:'B runs while A waits.',k:'# in B: build the request and send it'},
  {q:['C'],r:null,w:['main','A','B'],d:[],t:'B suspends too',c:'Two requests are now in flight at once.',k:'resp = await client.get(url)   # in B'},
  {q:[],r:'C',w:['main','A','B'],d:[],t:'Next in line: C',c:'C runs while A and B wait.',k:'# in C: build the request and send it'},
  {q:[],r:null,w:['main','A','B','C'],d:[],t:'Everyone is waiting: the thread is idle',c:'All three waits overlap. In the sequential version this time was spent three times over.',k:'# nothing is ready; the loop sleeps until a socket is readable'},
  {q:['A'],r:null,w:['main','B','C'],d:[],t:'A response arrives',c:'The loop notices the data, and A goes back on the ready queue.',k:'# A is ready again'},
  {q:[],r:'A',w:['main','B','C'],d:[],t:'A resumes where it left off',c:'It handles the response and returns.',k:'return parse(resp)   # in A'},
  {q:[],r:null,w:['main','B','C'],d:['A'],t:'A is finished',c:'The result is stored on the task object, so awaiting it again would just read it.',k:"A.result() == 'A'"},
  {q:['B'],r:null,w:['main','C'],d:['A'],t:'B response arrives',c:'B is back on the queue.',k:'# B is ready again'},
  {q:[],r:'B',w:['main','C'],d:['A'],t:'B resumes',c:'It handles its response and returns.',k:'return parse(resp)   # in B'},
  {q:[],r:null,w:['main','C'],d:['A','B'],t:'B is finished',c:'Two of three done.',k:"B.result() == 'B'"},
  {q:['C'],r:null,w:['main'],d:['A','B'],t:'C response arrives',c:'C is back on the queue.',k:'# C is ready again'},
  {q:[],r:'C',w:['main'],d:['A','B'],t:'C resumes',c:'It handles its response and returns.',k:'return parse(resp)   # in C'},
  {q:[],r:null,w:['main'],d:['A','B','C'],t:'All tasks are finished',c:'gather has what it was waiting for, so main can be woken.',k:'# every task passed to gather is done'},
  {q:['main'],r:null,w:[],d:['A','B','C'],t:'main is ready again',c:'It joins the queue like any other task.',k:'# main is ready again'},
  {q:[],r:'main',w:[],d:['A','B','C'],t:'main resumes with the results',c:'gather returns them in input order. Total time is about one round trip, not three.',k:"results == ['A', 'B', 'C']"}
];

const chips = {};
const layer = document.getElementById('chips');
Object.keys(COL).forEach(id => {
  const g = document.createElementNS(NS, 'g');
  g.setAttribute('class', 'chip');
  const r = document.createElementNS(NS, 'rect');
  r.setAttribute('width', 44);
  r.setAttribute('height', 32);
  r.setAttribute('rx', 6);
  r.setAttribute('fill', COL[id][0]);
  r.setAttribute('stroke', COL[id][1]);
  r.setAttribute('stroke-width', 0.5);
  const t = document.createElementNS(NS, 'text');
  t.setAttribute('class', 'th');
  t.setAttribute('x', 22);
  t.setAttribute('y', 16);
  t.setAttribute('text-anchor', 'middle');
  t.setAttribute('dominant-baseline', 'central');
  t.style.fill = COL[id][1];
  t.textContent = id;
  g.appendChild(r);
  g.appendChild(t);
  layer.appendChild(g);
  chips[id] = g;
});

function place(id, s) {
  const qi = s.q.indexOf(id), wi = s.w.indexOf(id), di = s.d.indexOf(id);
  if (s.r === id) return [339, 63, 1];
  if (qi >= 0) return [28 + qi * 50, 63, 1];
  if (wi >= 0) return [28 + wi * 50, 188, 1];
  if (di >= 0) return [450 + di * 50, 63, 1];
  return [28, 63, 0];
}

function setWrappedCaption(text) {
  const capEl = document.getElementById('cap');
  const codeBox = document.getElementById('code-box');
  const codeTxt = document.getElementById('code');
  const svgEl = document.documentElement;
  const bgEl = document.getElementById('page-bg');

  while (capEl.firstChild) capEl.removeChild(capEl.firstChild);

  if (text.length <= 82) {
    capEl.textContent = text;
    codeBox.setAttribute('y', 34);
    codeTxt.setAttribute('y', 49);
    svgEl.setAttribute('viewBox', '0 0 680 446');
    bgEl.setAttribute('height', 446);
  } else {
    const mid = text.lastIndexOf(' ', 80);
    const line1 = text.slice(0, mid);
    const line2 = text.slice(mid + 1);
    const t1 = document.createElementNS(NS, 'tspan');
    t1.setAttribute('x', 0);
    t1.setAttribute('dy', 0);
    t1.textContent = line1;
    const t2 = document.createElementNS(NS, 'tspan');
    t2.setAttribute('x', 0);
    t2.setAttribute('dy', 18);
    t2.textContent = line2;
    capEl.appendChild(t1);
    capEl.appendChild(t2);
    codeBox.setAttribute('y', 52);
    codeTxt.setAttribute('y', 67);
    svgEl.setAttribute('viewBox', '0 0 680 464');
    bgEl.setAttribute('height', 464);
  }
}

let i = 0, timer = null;
function render() {
  const s = S[i];
  Object.keys(chips).forEach(id => {
    const [p, q, v] = place(id, s);
    chips[id].style.transform = 'translate(' + p + 'px,' + q + 'px)';
    chips[id].style.opacity = v;
  });
  const busy = s.r !== null;
  document.getElementById('thr').style.fill = busy ? 'var(--bg-accent)' : 'var(--bg-neutral)';
  document.getElementById('thrs').textContent = busy ? 'thread busy' : 'thread idle';
  document.getElementById('ttl').textContent = s.t;
  setWrappedCaption(s.c);
  document.getElementById('code').textContent = s.k;
  document.getElementById('count').textContent = 'Step ' + (i + 1) + ' of ' + S.length;
}

function stop() {
  clearInterval(timer);
  timer = null;
  document.getElementById('play-lbl').textContent = 'Play';
}

function start() {
  if (i >= S.length - 1) i = 0;
  render();
  document.getElementById('play-lbl').textContent = 'Pause';
  timer = setInterval(() => {
    if (i < S.length - 1) {
      i++;
      render();
    } else {
      stop();
    }
  }, 1700);
}

document.getElementById('next').addEventListener('click', () => { stop(); if (i < S.length - 1) i++; render(); });
document.getElementById('back').addEventListener('click', () => { stop(); if (i > 0) i--; render(); });
document.getElementById('reset').addEventListener('click', () => { stop(); i = 0; render(); });
document.getElementById('play').addEventListener('click', () => { timer === null ? start() : stop(); });

document.addEventListener('keydown', e => {
  if (e.key === 'ArrowRight') { stop(); if (i < S.length - 1) i++; render(); }
  else if (e.key === 'ArrowLeft') { stop(); if (i > 0) i--; render(); }
  else if (e.key === ' ') { e.preventDefault(); timer === null ? start() : stop(); }
});

render();
setTimeout(start, 700);
